<script setup>
import {ref,computed,watch,onMounted,onUnmounted,nextTick} from 'vue'
import {Users,Flower2,Search,Plus,ArrowUpRight,ArrowRight,MapPin,Clock3,RefreshCw,Inbox,Check,Copy} from 'lucide-vue-next'
import {api,auth,labels,flowers,date,age} from '../api'
import Sheet from './Sheet.vue'
import PartnerForm from './PartnerForm.vue'
import PartnerApply from './PartnerApply.vue'
const props=defineProps({personal:Boolean,pendingCount:{type:Number,default:0}}),emit=defineEmits(['login','notice','refresh','report'])
const view=ref(props.personal?'cards':'browse'),category=ref('all'),query=ref(''),flower=ref(''),cards=ref([]),total=ref(0),page=ref(1),more=ref(false),loading=ref(true),error=ref('')
const mine=ref({cards:[],incoming:[],outgoing:[]}),characters=ref([]),sheet=ref(''),detail=ref(null),intent=ref(null),selected=ref(null),editing=ref(null),preset=ref('recruit'),busy=ref(false),confirmed=ref(false),cancelConfirm=ref(false)
let timer,searchTimer,serial=0,pendingAction=null,disposed=false
const roleName=r=>r==='priest'?'祭司':'打手'
const cardTitle=c=>c.kind==='job'?'祭司求职':`招募${c.target_job==='龙骑士'?'龙骑':roleName(c.target_role)}队友`
const stateName=r=>r.status==='accepted'?'待队长确认入队':r.kind==='job'&&r.status==='active'?'求职中':labels[r.status]||r.status
const price=c=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(Number(c.hourly_rate))+(c.price_currency==='rmb'?' RMB':' 游戏币')
const owns=c=>mine.value.cards.some(x=>x.id===c.id)
const rows=computed(()=>view.value==='browse'?cards.value:mine.value[view.value]||[])
const title=computed(()=>sheet.value==='publish'?(editing.value?'编辑队友信息':preset.value==='job'?'发布祭司求职':'发布队友招募'):sheet.value==='apply'?(selected.value?.kind==='job'?'邀请祭司入队':'申请成为队友'):sheet.value==='intent'?'组队意向':'队友详情')
async function load(append=false,silent=false){const id=++serial;if(!silent)loading.value=true;error.value='';try{const qs=new URLSearchParams({q:query.value,page:append?page.value+1:1});if(category.value==='job')qs.set('kind','job');else if(category.value!=='all'){qs.set('kind','recruit');qs.set('target_role',category.value)}if(flower.value)qs.set('flower',flower.value);const r=await api('/partners/cards?'+qs);if(id!==serial||disposed)return;cards.value=append?[...cards.value,...r.items]:r.items;page.value=r.page;total.value=r.total;more.value=r.has_more}catch(e){if(id===serial)error.value=e.message}finally{if(id===serial)loading.value=false}}
async function loadMine(){if(!auth.user)return;try{const r=await api('/partners/me');if(auth.user&&!disposed)mine.value=r}catch(e){error.value=e.message}}
async function prepare(action){if(!auth.user){pendingAction=action;sheet.value='';emit('login');return}try{characters.value=(await api('/me')).characters;await action()}catch(e){emit('notice',e.message)}}
async function publish(kind='recruit'){return prepare(()=>{editing.value=null;preset.value=kind;sheet.value='publish'})}
async function showIncoming(id){view.value='incoming';await loadMine();if(id)await openIntent(id)}
defineExpose({publish,showIncoming})
async function refresh(){await Promise.all([load(false,true),loadMine()]);emit('refresh')}
async function openCard(card){try{detail.value=await api('/partners/cards/'+card.id);sheet.value='detail'}catch(e){emit('notice',e.message)}}
async function apply(card){if(owns(card))return openCard(card);return prepare(()=>{selected.value=card;sheet.value='apply'})}
async function edit(){return prepare(()=>{editing.value=detail.value;sheet.value='publish'})}
async function openIntent(id){try{intent.value=await api('/partners/applications/'+id);confirmed.value=false;cancelConfirm.value=false;sheet.value='intent'}catch(e){emit('notice',e.message)}}
async function savedCard(card){await refresh();await openCard(card);emit('notice','已发布，合适的队友可以联系你')}
async function savedIntent(row){await loadMine();await openIntent(row.id);emit('notice',selected.value?.kind==='job'?'入队邀请已发送':'入队请求已发送')}
async function action(name){if(busy.value)return;busy.value=true;try{await api(`/partners/applications/${intent.value.id}/${name}`,{method:'POST',data:name==='join'?{wechat_confirmed:confirmed.value}:undefined});await openIntent(intent.value.id);await refresh();emit('notice',name==='join'?'已确认入队':name==='accept'?'已同意，双方现在可以添加微信':name==='cancel'?'意向已取消，联系方式不再开放':'已拒绝此意向')}catch(e){emit('notice',e.message)}finally{busy.value=false}}
async function status(name){if(busy.value)return;busy.value=true;try{await api(`/partners/cards/${detail.value.id}/status`,{method:'POST',data:{action:name}});await openCard(detail.value);await refresh();emit('notice',name==='matched'?'已停止招募，已有意向仍可确认入队':'卡片已下架')}catch(e){emit('notice',e.message)}finally{busy.value=false}}
async function removeContact(){if(busy.value)return;busy.value=true;try{const isIntent=sheet.value==='intent',resource=isIntent&&intent.value.side==='applicant'?'partner_app':'partner',id=resource==='partner_app'?intent.value.id:isIntent?intent.value.card.id:detail.value.id;await api(`/partners/contacts/${resource}/${id}`,{method:'DELETE'});if(isIntent)await openIntent(intent.value.id);else await openCard(detail.value);await loadMine();emit('notice','你的联系方式已删除')}catch(e){emit('notice',e.message)}finally{busy.value=false}}
async function copy(value){try{await navigator.clipboard.writeText(value);emit('notice','微信号已复制')}catch{emit('notice','请长按微信号复制')}}
function reportCard(id){sheet.value='';emit('report','partner',id)}
function changeView(v){if(v!=='browse'&&!auth.user){pendingAction=()=>{view.value=v;loadMine()};emit('login');return}view.value=v;if(v!=='browse')loadMine()}
watch([category,flower],()=>load())
watch(query,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>load(),300)})
watch(()=>auth.user,async user=>{if(!user){mine.value={cards:[],incoming:[],outgoing:[]};characters.value=[];sheet.value='';return}await loadMine();if(pendingAction){const action=pendingAction;pendingAction=null;await nextTick();await prepare(action)}})
onMounted(async()=>{await Promise.all([load(),loadMine()]);timer=setInterval(()=>{if(!document.hidden&&!sheet.value){if(view.value==='browse')load(false,true);if(auth.user)loadMine()}},30000)})
onUnmounted(()=>{disposed=true;clearInterval(timer);clearTimeout(searchTimer)})
</script>
<template><section class="partner-board">
  <div class="partner-intro"><div><h2>找个合拍的队友</h2><p>同意意向后交换微信，谈妥后由队长确认入队。</p></div><button class="button small" @click="publish('job')"><Flower2 :size="15"/>祭司求职</button></div>
  <nav class="partner-record-tabs" aria-label="队友记录"><button v-if="!personal" :class="{selected:view==='browse'}" @click="changeView('browse')">组队广场</button><button :class="{selected:view==='cards'}" @click="changeView('cards')">我的发布</button><button :class="{selected:view==='incoming'}" @click="changeView('incoming')">收到意向 <b v-if="pendingCount" class="notification-count">{{pendingCount>99?'99+':pendingCount}}</b></button><button :class="{selected:view==='outgoing'}" @click="changeView('outgoing')">已发意向 <b v-if="mine.outgoing.some(x=>x.can_confirm_join)">{{mine.outgoing.filter(x=>x.can_confirm_join).length}}</b></button></nav>
  <template v-if="view==='browse'"><div class="partner-categories" aria-label="队友类型"><button v-for="c in [['all','全部'],['fighter','招募打手'],['priest','招募祭司'],['job','祭司求职']]" :key="c[0]" :class="{selected:category===c[0]}" @click="category=c[0]">{{c[1]}}</button></div><div class="list-toolbar partner-toolbar"><label class="search-input"><Search :size="17"/><input v-model="query" aria-label="搜索队友、地图或职业" placeholder="搜索队友、地图、职业…"></label><select v-model="flower" aria-label="筛选花类型"><option value="">花类型不限</option><option value="active">活花</option><option value="afk">死花</option></select><button class="icon-button refresh-button" aria-label="刷新队友招募" @click="load()"><RefreshCw :size="17" :class="{spin:loading}"/></button></div><div class="list-caption"><span>最新发布 <b>{{total}}</b></span><span class="hint">同意交换微信 · 队长确认入队</span></div></template>
  <p v-if="error" class="error" role="alert">{{error}} <button class="text-button" @click="refresh">重新加载</button></p>
  <div v-if="loading&&!cards.length&&view==='browse'" class="cards-grid" aria-busy="true"><div v-for="n in 2" class="skeleton-card"><i></i><i></i><i></i></div></div>
  <div v-else-if="!rows.length" class="empty-state partner-empty"><div class="empty-art"><div class="orbit one"></div><div class="orbit two"></div><Users :size="44" stroke-width="1.2"/></div><h2>{{view==='browse'?(category!=='all'||query||flower?'暂时没有符合条件的队友':'好队友，从一声招呼开始'):view==='cards'?'还没有发布队友招募或求职':'暂时没有组队意向'}}</h2><p>{{view==='browse'?'招募打手或祭司，也可以亮出你的花类型与时薪。':view==='cards'?'发布队友招募或祭司求职，让合适的伙伴找到你。':'在组队广场发起联系，同意后交换微信。'}}</p><div class="button-row"><button class="button primary" @click="publish()"><Plus :size="15"/>发布队友招募</button><button class="button" @click="publish('job')"><Flower2 :size="15"/>祭司求职</button></div></div>
  <div v-else-if="view==='browse'||view==='cards'" class="cards-grid"><article v-for="c in rows" :key="c.id" class="team-card partner-card"><div class="card-top"><span class="tag" :class="{flower:c.kind==='job'||c.target_role==='priest'}"><Flower2 v-if="c.kind==='job'||c.target_role==='priest'" :size="12"/><Users v-else :size="12"/>{{cardTitle(c)}}</span><span class="card-state" :class="c.status"><i></i>{{stateName(c)}}</span></div><button class="card-title" @click="openCard(c)"><h3>{{c.game_id}}</h3><ArrowUpRight :size="18"/></button><div class="card-sub"><span>{{roleName(c.role)}}{{c.kind==='recruit'?'队长':''}}</span><span>Lv.{{c.level}}</span><span v-if="c.job">{{c.job}}</span></div><div class="partner-card-main"><template v-if="c.kind==='job'"><span class="tag flower" :class="c.flower">{{flowers[c.flower]}}</span><strong>{{price(c)}}<small> / 小时</small></strong></template><template v-else><span>寻找{{c.target_job||roleName(c.target_role)}} · Lv.{{c.level_min}}–{{c.level_max}}</span><span v-if="c.target_role==='priest'" class="tag flower">{{flowers[c.flower]}}</span></template></div><div class="card-time"><MapPin :size="14"/>{{c.map_name||'地图可商量'}}</div><div class="card-time"><Clock3 :size="14"/><span>{{c.start_time}} – {{c.end_time<=c.start_time?'次日 ':''}}{{c.end_time}}</span><small>北京时间</small></div><p v-if="c.notes" class="partner-note">{{c.notes}}</p><div class="card-bottom"><span class="hint">{{age(c.created_at)}}</span><button class="button card-cta" :disabled="c.status!=='active'&&!owns(c)" @click="owns(c)?openCard(c):apply(c)">{{owns(c)?'管理卡片':c.kind==='job'?'邀请入队':'申请入队'}}<ArrowUpRight :size="16"/></button></div></article></div>
  <div v-else class="partner-records"><button v-for="r in rows" :key="r.id" class="record-row" @click="openIntent(r.id)"><span class="record-icon"><Inbox :size="18"/></span><div><strong>{{view==='incoming'?r.game_id:r.card.game_id}} · {{cardTitle(r.card)}}</strong><small>{{roleName(view==='incoming'?r.role:r.card.role)}} · {{date(r.created_at)}}</small></div><span class="tag" :class="{'partner-action-tag':r.can_confirm_join||(r.status==='pending'&&r.side==='owner')}">{{stateName(r)}}</span><ArrowUpRight :size="16"/></button></div>
  <button v-if="view==='browse'&&more" class="button load-more" :disabled="loading" @click="load(true)">加载更多</button>
  <div class="how-it-works"><div><span>01</span><section><strong>找到打手或祭司</strong><p>招募队友，或邀请求职祭司</p></section></div><ArrowRight :size="15"/><div><span>02</span><section><strong>同意后添加微信</strong><p>双方沟通时间、费用与安排</p></section></div><ArrowRight :size="15"/><div><span>03</span><section><strong>队长确认入队</strong><p>在意向记录中完成确认</p></section></div></div>
</section>
<Sheet v-if="sheet" :key="sheet" :title="title" :wide="sheet==='publish'" @close="sheet=''">
  <PartnerForm v-if="sheet==='publish'" :initial="editing" :preset="preset" :characters="characters" @kind-change="preset=$event" @saved="savedCard"/>
  <PartnerApply v-else-if="sheet==='apply'" :card="selected" :characters="characters" @saved="savedIntent"/>
  <div v-else-if="sheet==='detail'" class="stack"><div class="partner-detail-heading"><span class="tag">{{cardTitle(detail)}}</span><span class="tag">{{stateName(detail)}}</span><h3>{{detail.game_id}} <small>Lv.{{detail.level}} · {{roleName(detail.role)}}</small></h3></div><div class="detail-grid"><div><small>地图</small><strong>{{detail.map_name||'可商量'}}</strong></div><div><small>在线时段 · 北京时间</small><strong>{{detail.start_time}} – {{detail.end_time<=detail.start_time?'次日 ':''}}{{detail.end_time}}</strong></div><div><small>{{detail.kind==='job'?'我的花类型':'寻找的队友'}}</small><strong>{{detail.kind==='job'?flowers[detail.flower]:(detail.target_job||roleName(detail.target_role))+(detail.target_role==='priest'?' · '+flowers[detail.flower]:'')}}</strong></div><div><small>{{detail.kind==='job'?'每小时收费':'队友等级要求'}}</small><strong>{{detail.kind==='job'?price(detail):'Lv.'+detail.level_min+'–'+detail.level_max}}</strong></div></div><p v-if="detail.notes" class="partner-detail-notes">{{detail.notes}}</p><p class="hint">发布于 {{date(detail.created_at)}} · 有效至 {{date(detail.expires_at)}}<br>发布账号：{{detail.publisher.name}}</p>
    <div v-if="detail.is_owner||detail.public_contact" class="contact-box"><h3>{{detail.is_owner?'我的联系方式':'发布者主动公开的联系方式'}}</h3><p v-if="(detail.contact||detail.public_contact)?.wechat">{{(detail.contact||detail.public_contact).wechat}}</p><img v-if="(detail.contact||detail.public_contact)?.qr" class="qr-preview" :src="(detail.contact||detail.public_contact).qr" alt="发布者微信二维码"><p v-if="!detail.contact&&!detail.public_contact" class="hint">联系方式已删除或过期</p></div>
    <template v-if="detail.is_owner"><div v-if="detail.status==='active'" class="button-row"><button class="button primary" :disabled="busy" @click="edit">编辑卡片</button><button class="button" :disabled="busy" @click="status('matched')">已找到，停止招募</button><button class="button subtle" :disabled="busy" @click="status('close')">下架</button></div><h3>收到的意向</h3><p v-if="!detail.applications.length" class="hint">还没有收到意向。</p><button v-for="r in detail.applications" :key="r.id" class="record-row" @click="openIntent(r.id)"><div><strong>{{r.game_id}} · {{roleName(r.role)}}</strong><small>Lv.{{r.level}}</small></div><span class="tag">{{stateName(r)}}</span><ArrowRight :size="16"/></button><button class="text-button" :disabled="busy" @click="removeContact">删除我的联系方式</button></template>
    <template v-else><button class="button primary full" :disabled="detail.status!=='active'" @click="apply(detail)">{{detail.kind==='job'?'邀请入队':'申请入队'}}</button><button class="text-button" @click="reportCard(detail.id)">举报此卡片</button></template>
  </div>
  <div v-else-if="sheet==='intent'" class="stack"><div class="partner-detail-heading"><span class="tag">{{stateName(intent)}}</span><h3>{{intent.card.game_id}} <ArrowRight :size="16"/> {{intent.game_id}}</h3><p class="hint">{{cardTitle(intent.card)}} · {{intent.card.map_name||'地图可商量'}}<br>队长：{{intent.captain_side==='owner'?intent.card.game_id:intent.game_id}}（{{intent.is_captain?'你':'对方'}}）</p></div><div class="detail-grid"><div><small>发起者角色</small><strong>{{roleName(intent.role)}} · Lv.{{intent.level}}</strong></div><div><small>{{intent.card.kind==='job'?'祭司时薪':'招募时段'}}</small><strong>{{intent.card.kind==='job'?price(intent.card):intent.card.start_time+' – '+(intent.card.end_time<=intent.card.start_time?'次日 ':'')+intent.card.end_time}}</strong></div><div v-if="intent.role==='priest'"><small>发起者花类型</small><strong>{{flowers[intent.flower]}}</strong></div><div v-if="intent.card.kind==='job'"><small>求职祭司花类型</small><strong>{{flowers[intent.card.flower]}}</strong></div></div><p v-if="intent.notes" class="partner-detail-notes">{{intent.notes}}</p>
    <div v-if="intent.status==='pending'" class="stack"><p class="hint">同意后开放双方微信；添加微信并谈妥后，再由队长确认入队。</p><div v-if="intent.side==='owner'" class="button-row"><button class="button primary" :disabled="busy" @click="action('accept')">同意并交换微信</button><button class="button" :disabled="busy" @click="action('reject')">拒绝</button></div><button v-else class="button" :disabled="busy" @click="action('cancel')">撤回意向</button></div>
    <template v-if="intent.contacts"><div v-for="side in ['publisher','applicant']" :key="side" class="contact-box"><h3>{{side==='publisher'?intent.card.game_id:intent.game_id}}的微信 <small>{{(side==='publisher')===(intent.side==='owner')?'（你）':'（对方）'}}</small></h3><p v-if="intent.contacts[side]?.wechat" class="partner-wechat"><strong>{{intent.contacts[side].wechat}}</strong><button class="button small" @click="copy(intent.contacts[side].wechat)"><Copy :size="14"/>复制</button></p><img v-if="intent.contacts[side]?.qr" class="qr-preview" :src="intent.contacts[side].qr" alt="微信二维码"><p v-if="!intent.contacts[side]" class="hint">联系方式已删除或过期，请通过已有沟通渠道联系。</p></div><button class="text-button" :disabled="busy" @click="removeContact">删除我的联系方式</button></template>
    <div v-if="intent.status==='accepted'" class="partner-join-box stack"><template v-if="intent.can_confirm_join"><strong>添加微信后，确认队友入队</strong><label class="check-label"><input v-model="confirmed" type="checkbox">我已与对方添加微信，并确认组队安排</label><button class="button primary full" :disabled="busy||!confirmed" @click="action('join')"><Check :size="17"/>确认入队</button></template><p v-else class="hint">{{intent.card.status!=='active'&&intent.card.status!=='matched'||new Date(intent.card.expires_at)<=new Date()?'卡片已结束或过期，不能继续确认入队。':intent.is_captain?'当前无法确认入队，请核对卡片和账号状态。':'添加微信并谈妥后，等待队长在页面确认入队。'}}</p></div><div v-if="intent.status==='joined'" class="partner-join-box"><strong><Check :size="17"/> 队长已确认入队</strong><p class="hint">{{date(intent.joined_at)}}</p></div>
    <div v-if="['accepted','joined'].includes(intent.status)"><button v-if="!cancelConfirm" class="text-button" @click="cancelConfirm=true">取消组队意向</button><div v-else class="stack"><p class="hint">取消后，本站不再向双方展示此意向的微信。已添加的微信好友关系不受影响。</p><div class="button-row"><button class="button" :disabled="busy" @click="action('cancel')">确认取消</button><button class="button subtle" @click="cancelConfirm=false">保留意向</button></div></div></div><button class="text-button" @click="reportCard(intent.card.id)">举报卡片 / 请求复核</button>
  </div>
</Sheet></template>
